AssistantMessageToolRequest(name='create', tool_call_id='tooluse_Nc5UlYZuIslAVJYDvsqlxV', arguments={'file_text': 'const form = document.getElementById('contactForm');
const fullNameInput = document.getElementById('fullName');
const emailInput = document.getElementById('email');
const phoneInput = document.getElementById('phone');

function validateFullName(value) {
    const trimmed = value.trim();
    if (!trimmed) {
        return 'Error: Full name is required.';
    }
    if (trimmed.length < 2) {
        return 'Error: Full name must be at least 2 characters.';
    }
    return '';
}

function validateEmail(value) {
    const trimmed = value.trim();
    if (!trimmed) {
        return 'Error: Email address is required.';
    }
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(trimmed)) {
        return 'Error: Please enter a valid email address.';
    }
    return '';
}

function validatePhone(value) {
    if (!value.trim()) {
        return '';
    }
    const phoneRegex = /^[\d\s\-()+.]*$/;
    if (!phoneRegex.test(value)) {
        return 'Error: Phone number contains invalid characters.';
    }
    return '';
}

function setFieldError(input, errorElement, errorMessage) {
    if (errorMessage) {
        input.setAttribute('aria-invalid', 'true');
        errorElement.textContent = errorMessage;
    } else {
        input.setAttribute('aria-invalid', 'false');
        errorElement.textContent = '';
    }
}

function validateField(input) {
    const errorElement = document.getElementById(`${input.id}-error`);
    if (!errorElement) return true;

    let errorMessage = '';
    if (input.id === 'fullName') {
        errorMessage = validateFullName(input.value);
    } else if (input.id === 'email') {
        errorMessage = validateEmail(input.value);
    } else if (input.id === 'phone') {
        errorMessage = validatePhone(input.value);
    }

    setFieldError(input, errorElement, errorMessage);
    return !errorMessage;
}

fullNameInput.addEventListener('blur', () => validateField(fullNameInput));
emailInput.addEventListener('blur', () => validateField(emailInput));
phoneInput.addEventListener('blur', () => validateField(phoneInput));

fullNameInput.addEventListener('input', () => {
    if (fullNameInput.getAttribute('aria-invalid') === 'true') {
        validateField(fullNameInput);
    }
});

emailInput.addEventListener('input', () => {
    if (emailInput.getAttribute('aria-invalid') === 'true') {
        validateField(emailInput);
    }
});

phoneInput.addEventListener('input', () => {
    if (phoneInput.getAttribute('aria-invalid') === 'true') {
        validateField(phoneInput);
    }
});

form.addEventListener('submit', (e) => {
    e.preventDefault();

    const isFullNameValid = validateField(fullNameInput);
    const isEmailValid = validateField(emailInput);
    const isPhoneValid = validateField(phoneInput);

    if (!isFullNameValid || !isEmailValid || !isPhoneValid) {
        const firstInvalid = document.querySelector('[aria-invalid="true"]');
        if (firstInvalid) {
            firstInvalid.focus();
        }
        return;
    }

    alert('Thank you for contacting support! We will get back to you soon.');
    form.reset();

    fullNameInput.setAttribute('aria-invalid', 'false');
    emailInput.setAttribute('aria-invalid', 'false');
    phoneInput.setAttribute('aria-invalid', 'false');
});
