    const htmlPath = path.join(__dirname, 'index.html');
    const htmlContent = fs.readFileSync(htmlPath, 'utf-8');

    await page.setContent(htmlContent, { waitUntil: 'load' });

    // Test 1: Initial state with no values
    console.log('\n=== Test 1: Initial State ===');
    await page.addScriptTag({ path: require.resolve('axe-core/axe.min.js') });
    let results = await page.evaluate(async () => {
        return await window.axe.run();
    });

    let wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
    if (wcag.length === 0) {
        console.log('✓ Initial state: PASS (32 rules passed)');
    } else {
        console.log('✗ Initial state: FAIL');
        wcag.forEach(v => console.log(`  - ${v.id}: ${v.description}`));
    }

    // Test 2: After setting invalid values and triggering validation
    console.log('\n=== Test 2: Invalid Input State ===');
    await page.fill('#fullName', 'A');
    await page.fill('#email', 'invalid-email');
    await page.fill('#phone', 'not-a-phone!!!');
    await page.click('#fullName');
    await page.blur('#fullName');

    // Re-inject axe for new content state
    await page.addScriptTag({ path: require.resolve('axe-core/axe.min.js') });
    results = await page.evaluate(async () => {
        return await window.axe.run();
    });

    wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
    if (wcag.length === 0) {
        console.log('✓ Invalid input state: PASS');
    } else {
        console.log('✗ Invalid input state: FAIL');
        wcag.forEach(v => console.log(`  - ${v.id}: ${v.description}`));
    }

    // Test 3: Check form semantics
    console.log('\n=== Test 3: Form Semantics ===');
    const formCheck = await page.evaluate(() => {
        const form = document.querySelector('form');
        const inputs = form.querySelectorAll('input');
        const labels = form.querySelectorAll('label');
        const errors = form.querySelectorAll('[role="alert"]');

        return {
            hasForm: !!form,
            inputCount: inputs.length,
            labelCount: labels.length,
            errorElements: errors.length,
            allInputsHaveLabels: Array.from(inputs).every(input => {
                const label = document.querySelector(`label[for="${input.id}"]`);
                return !!label;
            })
        };
    });

    console.log('✓ Form structure check:');
    console.log(`  - Form element: ${formCheck.hasForm}`);
    console.log(`  - Input count: ${formCheck.inputCount}`);
    console.log(`  - Label count: ${formCheck.labelCount}`);
    console.log(`  - Alert elements: ${formCheck.errorElements}`);
    console.log(`  - All inputs have labels: ${formCheck.allInputsHaveLabels}`);

    // Test 4: Keyboard navigation
    console.log('\n=== Test 4: Keyboard Navigation ===');
    await page.reload();
    await page.keyboard.press('Tab');
    const focusedElement1 = await page.evaluate(() => document.activeElement.id);
    await page.keyboard.press('Tab');
    const focusedElement2 = await page.evaluate(() => document.activeElement.id);

    console.log(`✓ Tab navigation works:`);
    console.log(`  - First Tab lands on: ${focusedElement1}`);
    console.log(`  - Second Tab lands on: ${focusedElement2}`);

    // Final re-test
    console.log('\n=== Final Test: Full Axe Run ===');
    await page.addScriptTag({ path: require.resolve('axe-core/axe.min.js') });
    results = await page.evaluate(async () => {
        return await window.axe.run();
    });

    wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
    const bp = results.violations.filter(v => v.tags.includes('best-practice'));

    console.log(`✓ WCAG violations: ${wcag.length}`);
    console.log(`✓ Best-practice warnings: ${bp.length}`);
    console.log(`✓ Rules passed: ${results.passes.length}`);

    await browser.close();
})();

