const htmlContent = fs.readFileSync(path.join(__dirname, 'index.html'), 'utf-8');

const checks = {
  'HTML lang attribute': htmlContent.includes('lang="en"'),
  'Title element': htmlContent.includes('<title>Support Contact Form</title>'),
  'Semantic main element': htmlContent.includes('<main>'),
  'Form element': htmlContent.includes('<form'),
  'novalidate on form': htmlContent.includes('novalidate'),
  'Labels for inputs': {
    fullName: htmlContent.includes('<label for="fullName">'),
    email: htmlContent.includes('<label for="email">'),
