    fullName: htmlContent.includes('Full name <span aria-hidden="true">*</span>'),
    email: htmlContent.includes('Email address <span aria-hidden="true">*</span>')
  },
  'Input types correct': {
    text: htmlContent.includes('type="text"'),
    email: htmlContent.includes('type="email"'),
    tel: htmlContent.includes('type="tel"')
  },
  'Autocomplete attributes': {
    name: htmlContent.includes('autocomplete="name"'),
    email: htmlContent.includes('autocomplete="email"'),
    tel: htmlContent.includes('autocomplete="tel"')
  },
  'Required attributes': {
    fullName: htmlContent.includes('id="fullName"') && htmlContent.match(/fullName[\s\S]*?required/),
    email: htmlContent.includes('id="email"') && htmlContent.match(/email[\s\S]*?required/)
  },
  'Error messages with aria-describedby': htmlContent.includes('aria-describedby="fullName-error"') && htmlContent.includes('aria-describedby="email-error"'),
  'Error alerts with role="alert"': (htmlContent.match(/role="alert"/g) || []).length >= 2,
  'Helper text for phone': htmlContent.includes('Format: (123) 456-7890 or +1-234-567-8900'),
  'Submit button': htmlContent.includes('type="submit"') && htmlContent.includes('Send message'),
  'CSS file linked': htmlContent.includes('href="styles.css"'),
  'JS file linked': htmlContent.includes('src="script.js"'),
  'Dark theme styles present': fs.readFileSync(path.join(__dirname, 'styles.css'), 'utf-8').includes('background: linear-gradient'),
  'Validation in JavaScript': fs.readFileSync(path.join(__dirname, 'script.js'), 'utf-8').includes('validateEmail'),
  'Form-field wrapper divs': (htmlContent.match(/class="form-field"/g) || []).length === 3
};

let passed = 0;
let total = 0;

const checkItem = (name, value) => {
  total++;
  if (typeof value === 'object') {
    const allTrue = Object.values(value).every(v => v);
    if (allTrue) {
      console.log('✓ ' + name);
      passed++;
    } else {
      console.log('✗ ' + name);
      Object.entries(value).forEach(([k, v]) => {
        if (!v) console.log('  - ' + k + ': missing');
      });
    }
  } else if (value) {
    console.log('✓ ' + name);
    passed++;
  } else {
    console.log('✗ ' + name);
  }
};

Object.entries(checks).forEach(([name, value]) => {
  checkItem(name, value);
});

console.log('\n' + passed + '/' + total + ' checks passed');
console.log('\n=== AXED-CORE TEST RESULT ===\n');

const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
